<?php $__env->startPush('scripts'); ?><script>document.addEventListener('DOMContentLoaded',()=>{const select=document.getElementById('ec-saved-address');select?.addEventListener('change',()=>{if(!select.value)return;const data=select.selectedOptions[0].dataset;const form=document.getElementById('sf-checkout-form');for(const [name,key] of Object.entries({customer_name:'recipient',customer_phone:'phone',district:'district',city:'city',address_line:'address'})){const input=form.elements.namedItem(name);if(input){input.value=data[key];input.dispatchEvent(new Event('input',{bubbles:true}));input.dispatchEvent(new Event('change',{bubbles:true}));}}});});</script><?php $__env->stopPush(); ?>

